function seo_checks(array $site,array $pages):array{$w=[];$titles=[];foreach($pages as $p){if($p['status']!=='published')continue;if(empty($p['seo']['description']))$w[]=$p['title'].': add a unique search description.';$title=$p['seo']['title']?:$p['title'];if(isset($titles[$title]))$w[]=$p['title'].': duplicate search title.';$titles[$title]=true;$heroes=0;foreach($p['sections'] as $sec){if(!empty($sec['hidden']))continue;if($sec['type']==='hero')$heroes++;if(!empty($sec['image'])&&empty($sec['alt']))$w[]=$p['title'].': an image is missing alternative text.';}if($heroes!==1)$w[]=$p['title'].': use one hero for a clear main heading.';}return $w;}
function check_links(Store $s):array{$pages=$s->get('pages',[]);$site=$s->get('site');$results=[];$inspect=function($label,$url,$id='')use($pages,&$results){if($id){$target=array_values(array_filter($pages,fn($p)=>$p['id']===$id));if(!$target)$results[]=['source'=>$label,'level'=>'error','message'=>'Destination page is missing.'];elseif($target[0]['status']!=='published')$results[]=['source'=>$label,'level'=>'warning','message'=>'Links to a private draft: '.$target[0]['title']];return;}if($url&&str_starts_with($url,'/')&&!str_starts_with($url,'/media/')&&!in_array($url,['/search/','/blog/','/'],true)&&!array_filter($pages,fn($p)=>page_path($p)===$url&&$p['status']==='published'))$results[]=['source'=>$label,'level'=>'warning','message'=>'Check internal destination: '.$url];};$menu=function($items)use(&$menu,$inspect){foreach($items as $i){$inspect('Menu: '.$i['label'],$i['url']??'',$i['page']??'');$menu($i['children']??[]);}};$menu($site['menus']);$menu($site['footerMenus']);foreach($pages as $p)foreach($p['sections'] as $sec){$inspect($p['title'].' · '.$sec['type'],$sec['link']??'',$sec['linkPage']??'');foreach($sec['pricing']['plans']??[] as $plan)$inspect($p['title'].' · '.$plan['name'],$plan['link'],$plan['linkPage']);}foreach($s->get('links',[]) as $l)$inspect('Saved link: '.$l['label'],$l['url']??'',$l['page']??'');return $results;}
