function raw_body(int $max):string{if((int)($_SERVER['CONTENT_LENGTH']??0)>$max)fail(413,'Upload is too large.');$raw=file_get_contents('php://input',false,null,0,$max+1);if(strlen($raw)>$max)fail(413,'Upload is too large.');return $raw;}
function upload_image(Store $store):array{$existing=$store->get('media',[]);if(count($existing)>=3000)fail(400,'The image-library limit has been reached.');$used=array_sum(array_map(fn($m)=>(int)($m['size']??0)+(int)($m['sourceSize']??0),$existing));$quota=(int)(config()['mediaQuotaBytes']??536870912);$raw=raw_body(8*1024*1024);$info=@getimagesizefromstring($raw);$type=(new finfo(FILEINFO_MIME_TYPE))->buffer($raw);if(!$info||!in_array($type,['image/jpeg','image/png','image/gif','image/webp'],true)||$type!==($info['mime']??''))fail(400,'Upload a valid JPEG, PNG, WebP or GIF image.');$memory=ini_get('memory_limit');$limit=$memory==='-1'?268435456:(int)$memory*(str_ends_with(strtolower($memory),'g')?1073741824:(str_ends_with(strtolower($memory),'m')?1048576:(str_ends_with(strtolower($memory),'k')?1024:1)));$pixels=min(16000000,max(0,intdiv($limit-memory_get_usage(true)-16777216,8)));if($info[0]>12000||$info[1]>12000||$info[0]*$info[1]>$pixels)fail(413,'Image dimensions exceed this host’s safe decoding limit. Resize it before uploading.');$image=@imagecreatefromstring($raw);if(!$image)fail(400,'The image cannot be decoded.');$id=uid();$sourceExt=['image/jpeg'=>'jpg','image/png'=>'png','image/gif'=>'gif','image/webp'=>'webp'][$type];$ext=$sourceExt==='gif'?'png':$sourceExt;$filename=$id.'.'.$ext;$path=private_dir().'/media/'.$filename;try{imagealphablending($image,false);imagesavealpha($image,true);$ok=match($ext){'jpg'=>imagejpeg($image,$path,88),'webp'=>imagewebp($image,$path,88),default=>imagepng($image,$path,6)};if(!$ok)fail(500,'Unable to save image.');}finally{imagedestroy($image);}chmod($path,0600);if($used+filesize($path)+strlen($raw)>$quota){unlink($path);fail(413,'The media storage quota has been reached.');}$sourceFile=$id.'.'.$sourceExt;atomic_write(private_dir().'/originals/'.$sourceFile,$raw);$item=['id'=>$filename,'url'=>'/media/'.$filename,'size'=>filesize($path),'created'=>stamp(),'width'=>$info[0],'height'=>$info[1],'sourceFile'=>$sourceFile,'sourceSize