 if($path==='/api/backup-ticket'&&$method==='POST'){owner($u);$b=input_json();limited($s,'reauth',10,900);$user=$s->query('SELECT hash FROM cms_users WHERE id=?',[$u['user_id']])->fetch();if(!password_verify((string)($b['password']??''),$user['hash']))fail(403,'Current password is incorrect.');step_up($s,$u,$b['factor']??'');$raw=bin2hex(random_bytes(32));$s->set('backupTickets',['hash'=>hash('sha256',$raw),'user'=>$u['user_id'],'expires'=>time()+60]);json_response(['ticket'=>$raw]);}
