function validate_directory_item(string $key,array $b,array $rows,Store $s):array{$id=txt($b['id']??'',80)?:uid();if($key==='categories'){$name=txt($b['name']??'',100);$slug=strtolower(txt($b['slug']??'',100));if(!$name||!preg_match('/^[a-z0-9]+(-[a-z0-9]+)*$/D',$slug))fail(400,'Enter a category name and lowercase slug.');foreach($rows as $r)if($r['id']!==$id&&$r['slug']===$slug)fail(409,'This category slug is in use.');return ['id'=>$id,'name'=>$name,'slug'=>$slug,'description'=>txt($b['description']??'',2000),'revision'=>uid()];}$label=txt($b['label']??'',200);$page=txt($b['page']??'',80);$category=txt($b['category']??'',80);$url=safe_url($b['url']??'');if(!$label||(!$page&&!$url))fail(400,'A link needs a label and destination.');if($page&&!in_array($page,array_column($s->get('pages',[]),'id'),true))fail(400,'Destination page missing.');if($category&&!in_array($category,array_column($s->get('categories',[]),'id'),true))fail(400,'Link category missing.');return ['id'=>$id,'label'=>$label,'page'=>$page,'category'=>$category,'url'=>$page?'':$url,'description'=>txt($b['description']??'',2000),'newTab'=>!empty($b['newTab']),'nofollow'=>!empty($b['nofollow']),'sponsored'=>!empty($b['sponsored']),'revision'=>uid()];}
