 if(str_starts_with($path,'/assets/')){if(!in_array($method,['GET','HEAD'],true))fail(405,'Method not allowed.');$name=substr($path,8);$allowed=in_array($name,['site.css','templates.css','site.js','admin.css','admin.js'],true);if(preg_match('~^starter-images/([a-z-]+)\.jpg$~D',$name,$m)&&isset(catalog()['bundles'][$m[1]]))$allowed=true;if(!$allowed)fail(404,'Asset not found.');file_response(CMS_ROOT.'/assets/'.$name,mime($name));}
 if(in_array(explode('/',trim($path,'/'))[0],['app','tests','docs','.git'],true)||$path==='/router.php')fail(404,'Not found.');
 if(str_starts_with($path,'/install')||!config()){require_once __DIR__.'/install.php';if($path==='/api/status')json_response(['configured'=>false,'starters'=>catalog()['starters']]);if(!str_starts_with($path,'/install')){header('Location: '.local_url('/install/'));exit;}web_install();}
 if(!tls()&&!localhost_request())fail(400,'Use HTTPS to access this installation.');$exclusive=!in_array($method,['GET','HEAD'],true)||in_array($path,['/api/backup/full','/api/export'],true);$lock=write_lock(private_dir(),$exclusive);if(is_file(restore_journal_path())&&!$exclusive){flock($lock,LOCK_UN);if(!flock($lock,LOCK_EX))fail(503,'Restore recovery is busy.');}$s=new Store();recover_interrupted_restore($s);
 if(str_starts_with($path,'/api/')){if(!in_array($method,['GET','HEAD'],true)&&$path!=='/api/contact')origin_check();api_request($s,$path,$method);}
 if(str_starts_with($path,'/recover')){require_once __DIR__.'/install.php';web_recovery($s);}
 if($path==='/admin'||$path==='/admin/')admin_page();
 if(preg_match('~^/media/([a-f0-9]{32}\.(png|jpg|gif|webp))$~D',$path,$m)){file_response(private_dir().'/media/'.$m[1],mime($m[1]));}
 if(str_starts_with($path,'/preview/')||str_starts_with($path,'/starter-preview/')){auth($s);header('X-Robots-Tag: noindex, nofollow');header('Cache-Control: no-store');$site=$s->get('site');$routes=[];$categories=$s->get('categories',[]);$links=$s->get('links',[]);$pages=$s->get('pages',[]);
