  else{$id=substr($path,9);$page=array_values(array_filter($pages,fn($p)=>$p['id']===$id))[0]??null;}if(!$page)fail(404,'Preview page not found.');if(isset($_GET['theme'])){$theme=array_values(array_filter(catalog()['themes'],fn($t)=>$t['id']===$_GET['theme']));if(!$theme)fail(400,'Unknown theme.');$site['theme']=$theme[0]['id'];if(($_GET['palette']??'')==='preset'||str_starts_with($path,'/starter-preview/')){$site['accent']=$theme[0]['accent'];$site['font']=$theme[0]['font'];}}
