 if(in_array($path,['/robots.txt','/sitemap.xml','/search-index.json'],true))file_response($dir.$path,mime($path));foreach(all_pages($snap['site'],$snap['pages'],$snap['categories'],$snap['links']) as $p){if($p['status']==='published'&&page_path($p)===$normalized){if($path!==$normalized){header('Location: '.local_url($normalized),true,301);exit;}file_response($dir.($p['slug']?'/'.$p['slug']:'').'/index.html','text/html; charset=utf-8');}}
