 }catch(Throwable $ex){error_log('1DED CMS: '.get_class($ex).' '.$ex->getMessage());if(str_starts_with($path??'','/api/'))json_response(['error'=>'Something went wrong. Check the hosting PHP error log.'],500);http_response_code(500);echo 'The CMS could not complete this request. Check the hosting PHP error log.';exit;}
